34;let s=i,l=t-50-280,u=l-50-28;e.fillStyle=`#000000`,e.font=`14.5px 'Consolas', 'Courier New', monospace`;let d=c(`I was born in San Cristóbal, a small mountain city in the state of Táchira, Venezuela. From an early age, I was curious about how things worked and why they were designed the way they were. That curiosity naturally evolved into an interest in the intersection of science, technology, and art, where analytical thinking meets creativity.`,50,s,u,23);d+=16,d=c(`During my second year of high school, I built an ethanol distiller as an alternative fuel source and won that year's science fair. Experiences like this encouraged me to explore how things could be designed, improved, and brought to life. Over time, I began studying programming more seriously while developing a deeper appreciation for the design of everyday objects and the reasoning behind seemingly small details, such as why certain indicators exist and how they communicate information.`,50,d,u,23);let f=d-s,p=s+Math.max(0,Math.round((f-395)/2));$u&&$u.complete&&$u.naturalWidth>0?(e.save(),e.shadowColor=`rgba(0, 0, 0, 0.12)`,e.shadowBlur=14,e.shadowOffsetY=4,e.fillStyle=`#ffffff`,e.roundRect?(e.beginPath(),e.roundRect(l,p,280,371,6),e.fill()):e.fillRect(l,p,280,371),e.restore(),e.save(),e.roundRect&&(e.beginPath(),e.roundRect(l,p,280,371,6),e.clip()),e.drawImage($u,l,p,280,371),e.restore(),e.save(),e.strokeStyle=`rgba(0, 0, 0, 0.15)`,e.lineWidth=1.5,e.roundRect?(e.beginPath(),e.roundRect(l,p,280,371,6),e.stroke()):e.strokeRect(l,p,280,371),e.restore()):(e.save(),e.fillStyle=`rgba(0, 0, 0, 0.04)`,e.strokeStyle=`rgba(0, 0, 0, 0.12)`,e.lineWidth=1,e.roundRect?(e.beginPath(),e.roundRect(l,p,280,371,6),e.fill(),e.stroke()):(e.fillRect(l,p,280,371),e.strokeRect(l,p,280,371)),e.fillStyle=`#777777`,e.font=`italic 13px 'Consolas', monospace`,e.textAlign=`center`,e.fillText(`Loading ramy02.jpg...`,l+140,p+371/2),e.restore()),e.save(),e.font=`italic 13px 'Consolas', monospace`,e.fillStyle=`#555555`,e.textAlig